"""Build standalone, non-authenticating login concepts for visual comparison."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "static" / "login-concepts"
OUT.mkdir(exist_ok=True)
CONCEPTS = [
    ("panorama", "Campus panorama", "Closest to your reference", "Sharp campus artwork, white editorial text, and a clear white login panel.", "Strong atmosphere; the illustration competes more with the message.", "Reunite with what<br>you’ve misplaced."),
    ("split", "White campus split", "Recommended", "A clean white page, a sharp illustration window, and green typography.", "Best balance of readability, illustration, and compact mobile layout.", "A familiar place.<br>A way back."),
    ("ticket", "Return ticket", "Most distinctive", "A campus claim-ticket motif gives the sign-in form a purpose-built identity.", "Memorable and focused; less emphasis on the campus illustration.", "Small things.<br>Worth returning."),
    ("gateway", "Quiet gateway", "Most focused", "One centered sign-in surface with a restrained campus strip and generous white space.", "Fastest to scan; less room to explain how matching works.", "Welcome back.<br>Let’s find your stuff."),
    ("sidepanel", "Campus side panel", "Most practical", "An illustration panel frames a simple, card-free sign-in column.", "Strong desktop structure; becomes a compact illustrated header on mobile.", "Lost something?<br>Start here."),
]
BAG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="5" y="8" width="14" height="13" rx="2"/><path d="M9 8V6a3 3 0 0 1 6 0v2M12 12v4"/></svg>'
BRAND = f'<a class="brand" href="index.html"><span class="brand-mark">{BAG}</span><span>Where Is My Stuff?<small>Lost &amp; Found</small></span></a>'
FORM = '''<section class="account" aria-labelledby="account-heading">
<nav class="tabs" aria-label="Account access"><button type="button" class="active" data-tab="login" aria-pressed="true">Login</button><button type="button" data-tab="register" aria-pressed="false">Register</button></nav>
<h2 id="account-heading">Welcome back</h2><p class="form-intro">Sign in to manage your reports and QR labels.</p>
<form><label for="email">Email</label><input id="email" name="username" type="email" placeholder="you@example.com" autocomplete="username" autocapitalize="none" spellcheck="false" required>
<label for="password">Password</label><div class="password-wrap"><input id="password" type="password" placeholder="Enter your password" autocomplete="current-password" required><button type="button" class="reveal" aria-controls="password" aria-pressed="false">Show</button></div>
<label class="remember"><input type="checkbox"> Remember me</label><button type="submit" class="submit">Log in</button><p class="status" role="status" hidden></p></form>
<p class="privacy">Your contact details are shared only after both people accept a handover.</p></section>'''

for slug, title, tag, description, tradeoff, heading in CONCEPTS:
    hero = f'''<section class="hero" aria-labelledby="hero-heading"><span class="service">Campus lost &amp; found</span><h1 id="hero-heading">{heading}</h1><p class="lede">Report a lost or found item. Review possible matches. Arrange its return together.</p><div class="campus-image" role="img" aria-label="Two students returning a lost wallet on campus"></div><div class="how"><span><b>Report</b>Lost or found</span><span><b>Review</b>Possible matches</span><span><b>Arrange</b>A safe handover</span></div><div class="ticket-stub"><span>Campus return desk</span>{BAG}<strong>A little care.<br>A way home.</strong><span>Keep your identifying details private.</span></div></section>'''
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} — Login concept</title><link rel="stylesheet" href="concepts.css"></head><body class="concept {slug}"><header>{BRAND}<span class="preview-label">Design preview</span></header><main>{hero}{FORM}</main><footer><span>We cannot guarantee the recovery of your item.</span></footer><script src="concepts.js"></script></body></html>'''
    (OUT / f"{slug}.html").write_text(html, encoding="utf-8")

sections = []
for index, (slug, title, tag, description, tradeoff, _) in enumerate(CONCEPTS, 1):
    sections.append(f'''<section class="option" id="{slug}"><div class="option-head"><div><p class="option-index">Concept {index} <span>{escape(tag)}</span></p><h2>{escape(title)}</h2><p>{escape(description)}</p></div><button class="choose" data-choice="{slug}" aria-pressed="false">Choose this direction</button></div><div class="previews"><div class="desktop-preview"><div class="frame-label"><b>Desktop</b><span>1280 × 720</span><a href="{slug}.html" target="_blank" rel="noopener">Open full size ↗</a></div><div class="desktop-frame"><div class="viewport desktop"><iframe title="{escape(title)} desktop preview" src="{slug}.html" width="1280" height="720"></iframe></div></div></div><div class="mobile-preview"><div class="frame-label"><b>Phone</b><span class="phone-size">390 × 844</span></div><div class="phone-frame"><div class="viewport phone"><iframe title="{escape(title)} phone preview" src="{slug}.html" width="390" height="844"></iframe></div></div></div></div><p class="tradeoff"><strong>How it weighs up:</strong> {escape(tradeoff)}</p></section>''')

gallery = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Five login directions — Where Is My Stuff?</title><link rel="stylesheet" href="gallery.css"></head><body><header class="gallery-header">''' + BRAND + '''<a class="current" href="/login/">Current login ↗</a></header><main><div class="gallery-intro"><div><span class="kicker">Where Is My Stuff? / Login exploration</span><h1>Five ways to feel at home.</h1><p>Compare the same campus lost-and-found service at desktop and phone sizes. Green and white. Sharp artwork. Readable type. A quiet disclaimer.</p></div><aside><strong>My starting pick: White campus split</strong><p>Clear text, a compact form, and room for the campus illustration without making it the background of your reading.</p></aside></div><div class="toolbar"><nav aria-label="Concepts">''' + ''.join(f'<a href="#{s}">{i} · {escape(t)}</a>' for i,(s,t,*_) in enumerate(CONCEPTS,1)) + '''</nav><label>Phone width <select id="phone-width"><option value="320">320 px · Small</option><option value="390" selected>390 px · Standard</option><option value="428">428 px · Large</option></select></label></div><p class="preview-note">These are interactive visual concepts. Try the password reveal and Login / Register tabs with sample values; they do not submit credentials or create accounts.</p><p class="selection" role="status" id="selection" hidden></p>''' + ''.join(sections) + '''<section class="research"><h2>What stays consistent</h2><p>Visible labels, email autocomplete, password-manager support, optional password reveal, 44 px phone controls, visible focus, and a small rounded recovery notice. The five concepts change layout and visual character, not the account requirements.</p><p>Research: <a href="https://www.w3.org/WAI/WCAG21/Techniques/html/H100" target="_blank" rel="noopener">W3C: accessible authentication fields</a> · <a href="https://www.nngroup.com/articles/checklist-registration-login/" target="_blank" rel="noopener">NN/g: mobile login guidance</a>.</p></section></main><footer class="gallery-footer">Choose a direction above. Your choice is saved only in this browser; the current login page is unchanged.</footer><script src="gallery.js"></script></body></html>'''
(OUT / "index.html").write_text(gallery, encoding="utf-8")
print(f"Built five concepts and gallery in {OUT}")
